#!/usr/bin/env python3
import argparse,base64,hashlib,json,os,subprocess,tempfile,zlib
from pathlib import Path
from uuid import uuid4
DATA=json.loads(zlib.decompress(base64.b64decode('')));PAYLOAD={k:base64.b64decode(v) for k,v in DATA["payload"].items()}
def norm(d):return d.decode("utf-8-sig").replace("\r\n","\n").rstrip("\n").encode()
def sha(d):return hashlib.sha256(norm(d)).hexdigest()
def atomic(p,d):
 p.parent.mkdir(parents=True,exist_ok=True);fd,t=tempfile.mkstemp(prefix=".labtools-lint-",dir=p.parent)
 try:
  with os.fdopen(fd,"wb") as f:f.write(d)
  os.replace(t,p)
 finally:Path(t).unlink(missing_ok=True)
def main():
 ap=argparse.ArgumentParser();g=ap.add_mutually_exclusive_group(required=True);g.add_argument("--check",action="store_true");g.add_argument("--apply",action="store_true");g.add_argument("--rollback",type=Path);ap.add_argument("--root",type=Path,default=Path.cwd());a=ap.parse_args();root=a.root.resolve()
 def git(*x):return subprocess.check_output(["git","-C",str(root),*x],text=True).strip()
 if Path(git("rev-parse","--show-toplevel")).resolve()!=root:raise RuntimeError("Run from repository root")
 if git("symbolic-ref","--short","HEAD") in {"main","master"}:raise RuntimeError("Refusing main/master")
 if a.rollback:
  rec=json.loads((a.rollback/"backup.json").read_text())
  for n,d in PAYLOAD.items():
   if (root/n).read_bytes()!=d:raise RuntimeError("Rollback would overwrite later edits: "+n)
  for n,v in rec["originals"].items():atomic(root/n,base64.b64decode(v))
  print("Rollback complete");return
 bad=[n for n,h in DATA["baseline"].items() if not (root/n).is_file() or sha((root/n).read_bytes())!=h]
 if bad:raise RuntimeError("Baseline mismatch: "+", ".join(bad))
 print(f"Baseline matches; {len(PAYLOAD)} files.")
 if a.check:return
 bd=root.parent/".labtools-backups"/(root.name+"-production-lint-"+uuid4().hex);bd.mkdir(parents=True)
 originals={n:base64.b64encode((root/n).read_bytes()).decode() for n in PAYLOAD};(bd/"backup.json").write_text(json.dumps({"root":str(root),"originals":originals},indent=2))
 try:
  for n,d in PAYLOAD.items():atomic(root/n,d)
 except BaseException:
  for n,v in originals.items():atomic(root/n,base64.b64decode(v))
  raise
 print("APPLIED. Backup: "+str(bd));print("No Git actions performed.")
if __name__=="__main__":
 try:main()
 except Exception as e:raise SystemExit("ERROR: "+str(e))
